function ErasedInformation(f, p, n, m):
    # source entropy
    Hs <- 0
    for x in 0..2^n-1:
        if p[x] > 0: Hs <- Hs - p[x]*ln(p[x])
    # pushforward (fiber sums)
    q <- array of 2^m zeros
    for x in 0..2^n-1:
        q[f(x)] <- q[f(x)] + p[x]
    # image entropy
    Hi <- 0
    for y in 0..2^m-1:
        if q[y] > 0: Hi <- Hi - q[y]*ln(q[y])
    erased <- Hs - Hi            # >= (n-m)*ln2 for uniform p
    return (erased, k*T*erased)

