function ResidueCompressor(n, m):
    require 0 <= m <= n
    modulus <- 2^m
    return  (function(i): return i mod modulus)
# guarantee: each fiber has exactly 2^(n-m) preimages;
#            pushforward of uniform is uniform;
#            erased information = (n-m)*ln2 exactly.
